function pipelineStageVersion(job){return job.type==='pipeline'?JSON.stringify([Object.values(job.stages||{}).map(stage=>stage.status),Object.values(job.stages?.cover?.coverStages||{}).map(stage=>stage.status)]):''}
function renderJobs(){const item=p();if(!item)return;const all=state.jobs.filter(x=>x.projectId===item.id),jobs=visualSpec.visibleProjectJobs(state.jobs,item.id),compositionReady=j=>j.result?.url&&(j.type==='pipeline'?j.stages?.export?.status==='done':j.type==='export'&&j.status==='done');
 const downloads=url=>`<div class="composition-downloads"><a class="btn primary download-link" href="${esc(url)}" download="${esc(item.name)}.mp4"><svg aria-hidden="true"><use href="#download"/></svg><span>下载视频</span><span class="download-format">MP4</span></a><a class="btn download-secondary download-link" href="/api/projects/${item.id}/subtitles" download="${esc(item.name)}.srt"><svg aria-hidden="true"><use href="#text"/></svg><span>下载字幕</span><span class="download-format">SRT</span></a></div>`;
 let html=jobs.map(j=>`<div class="job-box ${j.status==='error'?'error':''} ${compositionReady(j)?'composition-result':''}" data-job-id="${esc(j.id)}" data-job-type="${esc(j.type)}" data-job-status="${esc(j.status)}"><div class="row"><span>${({pipeline:'一键处理',transcribe:'字幕识别',chapters:'章节生成',copy:'平台文案',cover:'封面生成',export:'视频合成'})[j.type]}</span><span>${j.status==='running'?j.progress+'%':j.status==='done'?'已完成':'失败'}</span></div><div class="${j.status==='error'?'error-text':'subtext'}">${compositionReady(j)&&j.status==='done'?'文件已就绪，可下载到本机':esc(j.message)}</div>${j.status==='running'?`<div class="job-progress"><i style="width:${j.progress}%"></i></div>`:''}${j.type==='pipeline'?renderPipelineStages(j):''}${compositionReady(j)?downloads(j.result.url):''}</div>`).join('');
 // Keep the latest successful video downloadable during other tasks and failed retries.
 if(item.output&&!jobs.some(j=>compositionReady(j)&&j.result.url===item.output.url))html+=`<div class="job-box composition-result"><div class="row"><span>视频合成</span><span>已完成</span></div><div class="subtext">文件已就绪，可下载到本机</div>${downloads(item.output.url)}</div>`;
 if($('#jobArea'))$('#jobArea').innerHTML=html;
 renderCoverResults();renderTaskFeedback();renderPromptLogs();renderPipelinePanel();renderProjectExportButton();const busy=all.some(j=>j.status==='running')||Object.values(generationRequests).some(map=>map.get(item.id)?.status==='submitting');$('.saved').textContent=busy?'正在处理…':'项目已保存';}
function renderTaskResults(previous){
 const item=p();if(currentView!=='work')return;
 if(!previous||previous.id!==item?.id||renderedProjectId!==item.id||!$('#previewVideo')||previous.sourceUrl!==item.sourceUrl||JSON.stringify([previous.subtitles,previous.chapters])!==JSON.stringify([item.subtitles,item.chapters])){renderAll();return}
 // Cover feedback is already updated by renderJobs. Do not rebuild unrelated forms or media.
 if(JSON.stringify(previous.copy)!==JSON.stringify(item.copy))renderCopy();
 if(JSON.stringify(previous.output)!==JSON.stringify(item.output))renderExportPanel();
}
function schedulePoll(){clearTimeout(pollTimer);pollTimer=setTimeout(async()=>{try{const previousProject=p(),previous=new Map(state.jobs.filter(j=>j.status==='running').map(j=>[j.id,pipelineStageVersion(j)]));await refresh(false);if(state.jobs.some(j=>previous.has(j.id)&&(j.status!=='running'||pipelineStageVersion(j)!==previous.get(j.id))))renderTaskResults(previousProject);if(state.jobs.some(j=>j.status==='running'))schedulePoll()}catch(e){error(e);schedulePoll()}},1800)}
function renderPublish(){renderCopyWorkflow();renderCoverWorkflow();renderJobs()}
function renderCopyWorkflow(){const item=p();if(!item)return;
 $('#copySection .page-heading p').textContent='根据视频内容和自定义方向，生成四个平台的标题和一句话简介。';$('#copySection .mini-chip').textContent=item.subtitles.length?`已关联 ${item.subtitles.length} 句文稿`:'尚未识别文稿';
 const input=$('#creativePrompt');input.value=promptDrafts.get(item.id)??item.prompt??'';input.oninput=e=>editDirection('prompt',e.target.value);input.onblur=()=>saveDirections(item.id);
 $('#generateCopy').onclick=()=>startTask('copy',{prompt:input.value});$$('.platforms button').forEach((b,i)=>b.onclick=()=>{selectedPlatform=i;renderCopy()});$('#copySection .block-heading .text-button').onclick=downloadCopy;renderCopy();
}
function renderCoverSettings(){const item=p();if(!item)return;
 $('#coverSettings').innerHTML=[['horizontal','横版封面','coverHorizontal'],['vertical','竖版封面','coverVertical']].map(([slot,label,prefix])=>{const resolution=item.config[prefix+'Resolution'],ratio=item.config[prefix+'Ratio'],size=visualSpec.coverSize(resolution,ratio);return `<div class="cover-variant-settings"><h3>${label}</h3>${[['分辨率',prefix+'Resolution',resolution],['画面比例',prefix+'Ratio',ratio]].map(([name,key,value])=>`<div class="cover-param-row"><label for="${key}">${name}</label><button class="resolution-trigger unified-trigger" id="${key}" data-cover-param="${key}" data-menu-label="${label}${name}" aria-haspopup="listbox" aria-expanded="false"><span>${esc(value)}</span><svg><use href="#chevron"/></svg></button></div>`).join('')}<p class="cover-requested-size">${size.width} × ${size.height} px</p></div>`}).join('');
 $$('[data-cover-param]').forEach(button=>button.onclick=()=>{const key=button.dataset.coverParam,options=key.endsWith('Ratio')?visualSpec.coverRatioOptions:visualSpec.coverResolutionOptions;nameMenu(button,options.map(([id,name])=>({id,name})),p().config[key],async id=>{await changeConfig(key,id);renderCoverSettings();renderCoverFeedback();document.getElementById(key)?.focus()})});

 renderCoverFeedback();
}
function renderCoverResults(){const item=p(),root=$('.cover-results');if(currentView!=='work'||!item||!root)return;
 if(root.dataset.project!==item.id){root.replaceChildren();root.dataset.project=item.id}
 for(const [slot,label,prefix]of [['horizontal','横版封面','coverHorizontal'],['vertical','竖版封面','coverVertical']]){
  const record=item.cover?.[slot],url=item.cover?.[slot+'Url'],result=record|| (url?{url,...(state.artifacts||[]).find(a=>a.url===url)}:null),ratio=result?.ratio||item.config[prefix+'Ratio'],actual=result?.width&&result?.height?`${result.width} × ${result.height} px`:'';
  const signature=JSON.stringify([result,item.coverPlan?.id,item.coverPlan?.[slot],item.config[prefix+'Ratio'],item.config[prefix+'Resolution']]);const previous=root.querySelector(`[data-cover-slot="${slot}"]`);if(previous?.dataset.resultSignature===signature)continue;
  const template=document.createElement('template');template.innerHTML=`<article class="cover-result" data-cover-slot="${slot}"><div class="section-title"><h3>${label}</h3><span>${esc(result?.resolution||'')} ${esc(ratio)}</span></div><div class="cover-result-image" style="aspect-ratio:${ratio.replace(':','/')}">${result?`<img alt="${label}" src="${esc(result.url)}">`:`<span>点击「生成封面」生成横竖两版</span>`}</div>${result?`<div class="cover-result-footer"><span>${actual}</span><a class="btn quiet download-link" href="${esc(result.url)}" download="${label}.png"><svg><use href="#download"/></svg>下载${label}</a></div>${result.exactSize===false?'<p class="cover-size-warning">实际尺寸与请求不同，以服务商返回结果为准。</p>':''}`:''}${item.coverPlan?.[slot]?.prompt||result?.prompt?`<div class="cover-prompt-editor" data-cover-prompt-editor="${slot}"></div><div class="cover-regenerate"><button class="btn quiet" id="${slot==='horizontal'?'generateHorizontalCover':'generateVerticalCover'}" data-regenerate-cover="${slot}">重新生成</button><span class="subtext">使用当前提示词</span></div><div id="${slot==='horizontal'?'horizontalCoverStatus':'verticalCoverStatus'}" class="copy-generation-status hidden" role="status" aria-live="polite"></div>`:''}</article>`;const article=template.content.firstElementChild;article.dataset.resultSignature=signature;if(previous)previous.replaceWith(article);else root.append(article);
  const editor=article.querySelector('[data-cover-prompt-editor]'),st=editor&&coverPromptEditorState(item,slot);if(st)renderCoverPromptEditor(editor,st);const button=article.querySelector('[data-regenerate-cover]');if(button)button.onclick=()=>regenerateCover(slot);
 }
 renderCoverFeedback();
}
function renderCoverWorkflow(){const item=p();if(!item)return;renderCoverSettings();
 const input=$('#coverPrompt');input.value=coverDrafts.get(item.id)??item.coverDirection??'';input.oninput=e=>editDirection('coverDirection',e.target.value);input.onblur=()=>saveDirections(item.id);
 renderCoverResults();
 $('#generateCover').onclick=async()=>{const direction=$('#coverPrompt').value;await configSaveQueue;startTask('cover',{prompt:direction})};
 renderCoverFeedback();
 $('.cover-notes').innerHTML=`<div class="model-info"><span>图像模型</span><b>${esc(state.settings.imageModel)}</b></div>`;
 $('.footer-info').textContent='生成封面：重新策划两版提示词并生图。单张重新生成：使用当前提示词与已保存尺寸。';
}
function renderCopy(){const names=['抖音','视频号','小红书','B站'];$$('.platforms button').forEach((b,i)=>b.classList.toggle('chosen',i===selectedPlatform));const copy=p().copy?.platforms?.find(x=>x.platform===names[selectedPlatform])||p().copy?.platforms?.[selectedPlatform];$('#copyTitle').textContent=copy?.title||'等待生成标题';$('#copyText').textContent=copy?.description||'先识别视频讲话内容，再输入创作方向。';$('#hashtags').textContent=Array.isArray(copy?.tags)?copy.tags.map(x=>x.startsWith('#')?x:'#'+x).join('　'):'';for(const [id,key]of [['copyTitle','title'],['copyText','description']]){const el=document.getElementById(id);el.contentEditable=!!copy;el.onblur=async()=>{if(!copy)return;copy[key]=el.textContent;try{await api('/api/projects/'+p().id,{copy:p().copy},'PATCH');demo('文案修改已保存')}catch(e){error(e)}}}$$('.copy-label button').forEach((b,i)=>b.onclick=()=>document.getElementById(i?'copyText':'copyTitle').focus());$('.other-titles').innerHTML=copy?.alternatives?.map((t,i)=>`<div class="option"><i>${i+2}</i><span>${esc(t)}</span><button data-alt="${i}">使用</button></div>`).join('')||'';$$('[data-alt]').forEach(b=>b.onclick=async()=>{copy.title=copy.alternatives[Number(b.dataset.alt)];try{await api('/api/projects/'+p().id,{copy:p().copy},'PATCH');renderCopy()}catch(e){error(e)}});$('.copy-foot .btn').onclick=()=>{if(!copy)return demo('请先生成文案');navigator.clipboard.writeText(`${copy.title}\n\n${copy.description}\n\n${$('#hashtags').textContent}`).then(()=>demo('已复制当前平台文案')).catch(error)};}
function downloadCopy(){if(!p()?.copy)return demo('请先生成文案');const text=p().copy.platforms.map(x=>`${x.platform}\n${x.title}\n\n${x.description}\n${(x.tags||[]).join(' ')}\n`).join('\n────────────\n\n');const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=p().name+'-平台文案.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function startExport(){if(!p())return;const id=p().id,bitrateKbps=Number($('#inlineBitrate').value);
 if(exportPreparations.has(id)||generationRequests.export.get(id)?.status==='submitting'||state.jobs.some(j=>j.projectId===id&&visualSpec.taskLanes(j).includes('export')))return;
 exportPreparations.add(id);renderTaskFeedback();
 try{await configSaveQueue;if(p()?.id!==id)return;syncProject(p(),await api('/api/projects/'+id,{config:{...p().config,bitrateKbps}},'PATCH'));renderInspector();await startTask('export')}catch(e){error(e)}finally{exportPreparations.delete(id);renderJobs()}
}
async function oneClick(){await openPipelinePanel()}
import('/render-spec.js').then(module=>{visualSpec=module;return refresh()}).then(()=>{if(state.jobs.some(x=>x.status==='running'))schedulePoll();return api('/api/health')}).then(h=>{if(!h.ffmpeg||!h.ffprobe)demo('未找到 FFmpeg / FFprobe，请安装后加入 PATH')}).catch(error);
